-- Arzno (Rifts World Book 28): Techno-Wizard weapons, gear and body armor
-- 22 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~244-arzno-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Rifts World Book 28: Arzno, printed 75-90; extracted off renders, checked by
-- book-reconcile. Prices are the A.W.M. or Arzno figure (low end), other tiers
-- in cost_note; armor stores its main body as mdc. NOT ADDED: the TW "Vampire
-- Chaser" Steam Grenade (79). tw-vampire-chaser-steam-grenade (Book of Magic
-- p.329) stands; Arzno prints 5D6 Hit Points per melee round to vampires where
-- that row has 6D6, and 60 P.P.E. creation stats. Recorded in the survey.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('tw-stake-driver', 'TW Stake Driver', 'rifts', 'weapon', 6, 29000, '29,000 credits from A.W.M.; 20% more from a small-time TW dealer; 2-3 times from the Black Market (58,000 to 87,000 credits). Generally available only in the Southwest and Mexico.', 'Stake: 3D6 H.P./S.D.C., none to most M.D. creatures unless they are vulnerable to wood. Flamethrower: 3D6 M.D. Silver short sword: 1D6 H.P./S.D.C., double to the undead.', 1, 'Stakes 15 feet (4.6 m), -1 to strike for each additional 5 feet; flamethrower 50 feet (15.2 m)', '5 wooden stakes and one flamethrower blast. 5 P.P.E. or 10 I.S.P. gives five more stakes; each flame blast costs 5 P.P.E. or 10 I.S.P. The short sword needs no power.', 'Single shot; each stake or flame blast counts as one melee attack', NULL, NULL, NULL, 'Nicknamed "Stake, Decapitate, & Burn": a Techno-Wizard stake launcher with a flamethrower and a silver short sword built in. +1 to strike within 15 feet (4.6 m) for all its weapon systems. To create: 130 P.P.E.; Create Wood (10), Energy Bolt (5), Fireblast (8) and Telekinesis (8); a plasma quartz worth 1,500 credits and two small rubies worth 1,000 each.', 'Rifts World Book 28: Arzno - Vampire Incursion p.75-76', NULL),
  ('tw-water-pistol', 'TW Water Pistol', 'rifts', 'weapon', 1.9, 5000, '5,000 credits in Arzno and the Colorado Baronies; 6,000-7,000 most elsewhere in the southwest; 9,000-11,000 from the Black Market. Prices climb toward the Mexican border.', '2D6 Hit Points to vampires and beings vulnerable to water; no damage to humans, D-Bees and most other creatures', 0, '200 feet (61 m)', 'Each activation arms it with 40 blasts; 20 P.P.E. or 40 I.S.P. to charge and recharge', 'Single shot', NULL, NULL, NULL, 'A converted revolver or automatic pistol with a small water reservoir where the cylinder or clip was. The book says its water weapons are the Vampire Kingdoms ones restated with full stats and creation rules for Techno-Wizard characters; the Book of Magic rows (tw-plastic-water-pistol, tw-metal-water-pistol) hold the earlier figures, and this row holds Arzno''s. A backup weapon for hunters and popular with civilians: about 75% of Arzno''s citizens own one. W.P. Handguns applies. To create: 95 P.P.E.; Create Water (15), Energy Bolt (5) and Telekinesis (8); a large aquamarine of at least 1,500 credits, plus a small blue sapphire and a zircon (700 credits total), and about 40 credits of salvaged parts.', 'Rifts World Book 28: Arzno - Vampire Incursion p.76', NULL),
  ('tw-water-rifle', 'TW Water Rifle', 'rifts', 'weapon', 4, 20000, '20,000 credits in Arzno; 30,000 elsewhere; 40,000-60,000 from the Black Market.', 'Rifle blast: 4D6 Hit Points to vampires. Grenade blast: 1D4x10+4 Hit Points in a 10 foot (3 m) diameter; counts as two blasts', 0, 'Rifle 600 feet (183 m); grenade 200 feet (61 m)', '20 P.P.E. or 40 I.S.P. charges it with 40 blasts', 'Either mode counts as one melee attack', NULL, NULL, NULL, 'The standard anti-vampire weapon of the Arzno Mercenary Corps: a short, stocky water shotgun and grenade launcher worked by a pump. At least half of Arzno''s households own one. Uses W.P. Rifles or W.P. Heavy Military Weapons. Weighs twice as much in metal or ceramic. To create: 135 P.P.E.; Create Water (15), Energy Field (10) and Telekinesis (8); an aquamarine of at least 3,000 credits plus a quartz, a zircon and a sapphire (3,000 credits total); parts cost 50 credits in plastic or 120 in ceramic and metal.', 'Rifts World Book 28: Arzno - Vampire Incursion p.76-77', NULL),
  ('tw-water-cannon-arzno', 'TW Water Cannon', 'rifts', 'weapon', 12.2, 55000, '55,000 credits in Arzno; 65,000-70,000 elsewhere; 100,000-150,000 from the Black Market.', 'Vampires: 3D4x10 Hit Points plus a 01-80% chance of knockdown (lose initiative and one attack). Mortals: 1D4 S.D.C./H.P. plus knockdown: 01-80% for humans, 01-40% for Combat and Mining ''Borgs of 500-600 lbs, 01-20% for large power armor and giants over 600 lbs, none against anchored Glitter Boys, vehicles or giant robots', 0, '600 feet (183 m)', '20 P.P.E. or 40 I.S.P. charges it with 20 blasts', 'Single shot', NULL, NULL, NULL, 'Arzno''s heavy water cannon, a different weapon from the Book of Magic''s TW Water Cannon (tw-water-cannon). Needs P.S. 20 or better or is -4 to strike; setting it on its tripod takes one melee round. Uses W.P. Heavy M.D. Weapons. Half again as heavy in metal or ceramic. To create: 255 P.P.E.; Create Water (15), Power Bolt (20), Telekinesis (8) and Wind Rush (20); an aquamarine of at least 4,000 credits plus a diamond and two sapphires (5,000 credits total); parts cost 150 credits, or 350 in metal and ceramic.', 'Rifts World Book 28: Arzno - Vampire Incursion p.77-78', NULL),
  ('tw-wood-rail-gun', 'TW Wood Rail Gun', 'rifts', 'weapon', 80, 60000, '60,000 credits in Arzno; 75,000-90,000 elsewhere; 140,000-180,000 from the Black Market. Outlawed in the Vampire Kingdoms.', 'Single stake: 1D6x10 Hit Points to vampires, 4D6 S.D.C./H.P. to mortals, none to M.D. beings. Four-stake burst: 3D6x10 Hit Points to vampires, 3D4x10 S.D.C. to mortals, or 1 M.D. to an M.D.C. target', 0, '3000 feet (914 m)', '20 P.P.E. or 40 I.S.P. loads 80 stakes: 20 bursts or 80 single shots', 'Single shot or short burst', NULL, NULL, NULL, 'A conventional rail gun converted to fire magically created wooden stakes. Needs P.S. 20 or better or is -3 to strike. The weight is about 80-100 lbs (36-45 kg) without the drum or generator; the low figure is stored. The book prints household ownership as 05%. To create: 160 P.P.E.; Create Wood (20), Power Bolt (20) and Telekinesis (8); a rose quartz of 1,000+ credits and a green quartz of 1,500+, and a rail gun.', 'Rifts World Book 28: Arzno - Vampire Incursion p.78', NULL),
  ('tw-vamp-killer-2000', 'TW Vamp-Killer 2000', 'rifts', 'weapon', 30, 65000, '65,000 credits in Arzno; 85,000 elsewhere; 135,000-200,000 from the Black Market. Outlawed in the Vampire Kingdoms. The whole kit.', 'Chainsaw: 5D6+6 Hit Points to vampires and ordinary S.D.C. material. Grenade launcher: wood fragmentation 1D4x10+2 Hit Points to vampires in a 10 foot (3 m) radius, with a 01-05% chance of a heart hit that immobilizes as if staked; 2D6 S.D.C. to mortals. Cross spotlight: 3D6 Hit Points to vampires and holds them at bay', 0, 'Chainsaw: reach plus 2 feet (0.6 m); grenade launcher 200 feet (61 m); spotlight 100 feet (30.5 m)', 'Chainsaw runs 10 hours per charge of 15 P.P.E. or 30 I.S.P.; the launcher holds four grenades; the spotlight runs on a conventional or TW battery (effectively unlimited)', 'Each grenade counts as one melee attack and loading one is an action; the motor must be running to fire', NULL, NULL, NULL, 'A vampire hunter''s kit built round a Techno-Wizard chainsaw with an underslung wood-grenade launcher and a cross-shaped spotlight. A quarter of Arzno''s households own one. The kit also holds a 12 inch cross, six stakes and a mallet (1D4), a pocket mirror, a TW Storm Flare, a Globe of Daylight flare and two TW Steam Grenades. To create: 65 P.P.E.; Call Lightning (15), Energy Bolt (5) and Wind Rush (25); a clear quartz worth 1,200 credits and 10 feet of gold wire.', 'Rifts World Book 28: Arzno - Vampire Incursion p.78-79', NULL),
  ('tw-flash-bang-bomb', 'TW Flash-Bang Bomb', 'rifts', 'weapon', NULL, 600, '600 credits in Arzno; 1,000 elsewhere; 1,200-1,800 from the Black Market. Single use.', 'None. Blinded: -10 to strike, parry, dodge and disarm, no initiative, 01-50% chance of falling per 10 feet moved. Deafened: -6 on initiative, -4 to strike, parry and dodge, 01-50% chance of falling per moving action. The two are cumulative', 0, 'Thrown about 100 feet (30.5 m). Area: the stat line prints a 20 foot (6.1 m) area and the text a 10 foot (6.1 m) radius', 'Single use; 5 P.P.E. to arm', NULL, NULL, NULL, NULL, 'A magical stun grenade made from a jar, bulbs and wire. Save 14 or better vs magic, rolled twice (sight and hearing); attempting the save costs one melee action, and vampires and other supernatural beings suffer half the penalties for half the time. Full penalties for 1D6+1 melee rounds, then half for 1D6+4 more. It affects wearers of environmental and power armor, but not robotic or cybernetic eyes or monitors. To create: 45 P.P.E.; Blinding Flash (1), Call Lightning (15), Energy Bolt (5) and Thunderclap (4); four clear quartz worth 100 credits each, two 100-watt bulbs, wire and a jar.', 'Rifts World Book 28: Arzno - Vampire Incursion p.79-80', NULL),
  ('tw-lightning-mace', 'TW Lightning Mace', 'rifts', 'weapon', NULL, 40000, '40,000 credits in Arzno; 50,000-60,000 elsewhere; 80,000-120,000 from the Black Market. Silver spikes add 150 credits each.', 'Unactivated: 2D4 S.D.C.; silver spikes 4D4 Hit Points to vampires. Activated: 4D6 M.D. per strike, and 1D6 M.D. even on a successful parry; lightning bolt 3D6 M.D.', 1, 'Melee, 2 feet (0.6 m) long; lightning bolt 100 feet (30.5 m)', '12 P.P.E. or 24 I.S.P. per activation, lasting two melee rounds (30 seconds)', 'Each strike or bolt counts as one melee attack', NULL, NULL, NULL, 'A mace that crackles with lightning when activated. +1 to strike with the lightning bolt. To create: 80 P.P.E.; Call Lightning (15), Electric Arc (8) and Energy Field (10); an amethyst worth 60 credits and 4 feet of copper wire.', 'Rifts World Book 28: Arzno - Vampire Incursion p.80-81', NULL),
  ('tw-active-shield', 'TW Active Shield', 'rifts', 'gear', 2, 50000, '50,000 credits in Arzno; 70,000 in the Colorado Baronies; 100,000 elsewhere; 150,000 from the Black Market.', NULL, 0, 'A stationary bubble 8 feet (2.4 m) in diameter', '10 P.P.E. per activation; 100 M.D.C. for 5 minutes or until depleted', NULL, NULL, NULL, NULL, 'A force-field generator that raises a stationary protective bubble of 100 M.D.C. It is switched on by hand, and can also be set to switch itself on when the wearer is knocked unconscious. Two overlapping fields short each other out, costing another 10 P.P.E. A converted Naruni field generator doubles the duration and the M.D.C. To create: 100 P.P.E.; Deflect (10), Energy Field (10), Magic Shield (6) and Watchguard (10); a 5 carat purple garnet, a half carat orange diamond and an 8 carat tourmaline; parts 2,000-5,000 credits.', 'Rifts World Book 28: Arzno - Vampire Incursion p.81', NULL),
  ('tw-climbing-claws', 'TW Climbing Claws', 'rifts', 'gear', NULL, 5500, '5,500 credits in Arzno; 15,000 elsewhere; 30,000-50,000 from the Black Market. The bionic version costs ten times as much.', '+1D4 S.D.C. over a normal punch', 0, NULL, '4 P.P.E. or 8 I.S.P. per activation; 5 minutes', NULL, NULL, NULL, NULL, 'Hand-held climbing claws: activated, they give Climb 98% on rough surfaces and 68% on smooth ones. A bionic version is its own row (tw-bionic-climbing-claws). To create: 35 P.P.E.; Globe of Daylight (2) and Climb (3); a smoky quartz worth 70 credits.', 'Rifts World Book 28: Arzno - Vampire Incursion p.81-82', NULL),
  ('tw-bionic-climbing-claws', 'TW Bionic Climbing Claws', 'rifts', 'cybernetics', NULL, 55000, 'Ten times the hand-held claws'' price, which is 5,500 credits in Arzno, 15,000 elsewhere and 30,000-50,000 from the Black Market.', '3D4 S.D.C./H.P., or +2D4 M.D. against M.D. materials', 0, NULL, '4 P.P.E. or 8 I.S.P. per activation; 5 minutes', NULL, NULL, NULL, NULL, 'The bionic version of the TW Climbing Claws, converted from retractable finger blades, clawed feet or similar bionic devices: Climb 98% on rough surfaces and 68% on smooth ones while active. To create: 85 P.P.E.; Globe of Daylight (2), Climb (3) and Aura of Power (4); a smoky quartz worth 70 credits and a pink quartz of 100+ credits.', 'Rifts World Book 28: Arzno - Vampire Incursion p.81-82', NULL),
  ('tw-concealment-cloak', 'TW Concealment Cloak', 'rifts', 'gear', NULL, 75000, '75,000 credits in Arzno; 170,000-250,000 elsewhere; 350,000-500,000 from the Black Market. Rare; the Colorado Baronies cannot make it.', NULL, 0, NULL, 'The book prints the charge twice: 2 P.P.E. or 4 I.S.P. per object on the creation line, and 4 P.P.E. or 8 I.S.P. per object under Energy Requirements. 15 minutes', NULL, NULL, NULL, NULL, 'A cloak that magically hides up to four items in its sleeves and pockets, each no more than 6 lbs (2.7 kg) and no bigger than an energy pistol. Finding them takes a save vs magic: 19 or better on a casual search, 13 on a thorough one, 8 under close scrutiny. To create: 90 P.P.E.; Globe of Daylight (2), Concealment (6), Manipulate Objects (10) and Befuddle (6); four amethysts of 100+ credits and 10 feet of copper wire.', 'Rifts World Book 28: Arzno - Vampire Incursion p.82', NULL),
  ('tw-reading-glasses', 'TW Reading Glasses', 'rifts', 'gear', NULL, 60000, '60,000 credits in Arzno; 80,000-100,000 elsewhere; 200,000-300,000 from the Black Market.', NULL, 0, NULL, '10 P.P.E. or 20 I.S.P. per activation; 1 hour', NULL, NULL, NULL, NULL, 'Spectacles that let the wearer read most written languages; certain alien languages may not be readable. Spoken language is not covered, and the wearer needs Literacy at 50% or better. To create: 120 P.P.E.; Energy Bolt (5), Eyes of Thoth (8) and Instill Knowledge (15); two topaz (200 credits total) and two silver antennae.', 'Rifts World Book 28: Arzno - Vampire Incursion p.82-83', NULL),
  ('tw-security-scanner', 'TW Security Scanner', 'rifts', 'gear', NULL, 35000, '35,000 credits in Arzno; 50,000 elsewhere; 90,000-130,000 from the Black Market. One price line covers both the wand and the portal.', NULL, 0, '2 feet (0.6 m)', 'Wand: 5 P.P.E. or 10 I.S.P., two melee rounds (30 seconds). Portal: 10 P.P.E. or 20 I.S.P., about half a melee round', NULL, NULL, NULL, NULL, 'A hand-held wand or a walk-through portal for checkpoints. It reveals magically concealed objects, and compels truthful answers to three questions wired into it. To create: 60 P.P.E.; Detect Concealment (6), Lantern Light (1), See the Invisible (4) and Words of Truth (15); the portal adds Energy Field (10) and three times the crystals. The wand''s gems are an amber, three garnets and two clear quartz.', 'Rifts World Book 28: Arzno - Vampire Incursion p.83', NULL),
  ('tw-tactical-team-targeting-system', 'TW Tactical Team Targeting System', 'rifts', 'gear', NULL, 10300, '10,300 credits in Arzno; 21,000 elsewhere; 30,000-50,000 from the Black Market.', NULL, 0, '2,000 feet (610 m)', '6 P.P.E. or 12 I.S.P. per activation; 15 minutes', 'Painting a target counts as one melee action', NULL, NULL, NULL, 'The "TTT System": a visor and laser sight per team member. The sight''s pencil-thin beam, and the glow of the target it marks, are invisible except through the TTT optics; each unit has its own colour. +2 to strike on an Aimed Shot at a marked target. Six colours, for teams of six or fewer. To create: 330 P.P.E.; Distant Voice (10), Lantern Light (1), Light Target (6), Power Bolt (20) and Second Sight (20); per set, a one-carat alexandrite linked to a large clear quartz with gold wire for the visor and a clear quartz lens for the sight, about 1,000 credits.', 'Rifts World Book 28: Arzno - Vampire Incursion p.83-84', NULL),
  ('tw-translator', 'TW Translator', 'rifts', 'gear', NULL, 35000, '35,000 credits in Arzno; 50,000 elsewhere; 65,000-90,000 from the Black Market.', NULL, 0, NULL, '12 P.P.E. or 24 I.S.P. per activation; 20 minutes', NULL, NULL, NULL, NULL, 'Two-way translation of spoken language, one language at a time. To create: 220 P.P.E., plus 15 for each additional language; Energy Bolt (5), Tongues (12) and five Instill Knowledge (15 each); two quartz worth about 120 credits and six garnets worth 50.', 'Rifts World Book 28: Arzno - Vampire Incursion p.84', NULL),
  ('light-tw-body-armor', 'Light TW Body Armor', 'rifts', 'armor', 10, 30000, '30,000 credits from A.W.M.; 40,000-45,000 elsewhere; 60,000-90,000 from the Black Market.', 'Silver spikes add 1D6 S.D.C. against the undead', 0, 'Globe of Daylight 10 foot (3 m) radius', 'Armor of Ithan: 30 M.D.C., 10 P.P.E. or 20 I.S.P., 5 minutes (20 melee rounds) or until depleted, can be raised again one melee round later. Globe of Daylight: 3 P.P.E. or 6 I.S.P., 5 minutes', NULL, NULL, NULL, 35, 'Model Arzno TWA-900, for humans of 5-7 feet. Good mobility: -5% to prowl, swim and acrobatics. No A.R. printed. M.D.C. by location: head 35, arms 15 each, legs 15 each, force field emitter 8 and Globe of Daylight generator 5 (both called shots at -4), main body 35; the magic force field adds 30. No built-in weapons. Over half of Arzno''s households own a suit.', 'Rifts World Book 28: Arzno - Vampire Incursion p.85', NULL),
  ('tw-incursion-armor', 'TW Incursion Armor', 'rifts', 'armor', 12, 195000, '195,000 credits, exclusive to A.W.M.; 500,000 from the Black Market.', 'Silver spikes add 1D6 S.D.C. against the undead; two retractable silver short swords and an elbow blade, 2D4 S.D.C., double against vampires', 0, 'Flight pack 5,000 feet (1524 m) altitude; Globe of Silence 5 feet (1.5 m)', 'Armor of Ithan: 60 M.D.C., 15 P.P.E. or 30 I.S.P., 10 minutes. Flight pack: 25 P.P.E. or 50 I.S.P., 1 hour. Globe of Silence: 20 P.P.E. or 40 I.S.P., 5 minutes. Chameleon: 7 P.P.E. or 14 I.S.P., 20 minutes', NULL, NULL, NULL, 42, 'Model TWA-1500 Incursion E.B.A. Excellent mobility, no skill penalties. No A.R. printed. M.D.C. by location: head 50, arms 25 each, legs 30 each, force field emitter 8 and flight pack 25 (both called shots at -4), main body 42; the magic force field adds 60. The flight pack (Fly as the Eagle) flies at 75 mph (120 km) and gives +2 to dodge. The Globe of Silence blocks radio, speech and spell casting inside it. Chameleon works only at Spd 6 or less. A third of Arzno''s households own one.', 'Rifts World Book 28: Arzno - Vampire Incursion p.86-87', NULL),
  ('tw-exterminator-armor', 'TW Exterminator Armor', 'rifts', 'armor', 18, 185000, '185,000 credits from A.W.M. (competitors charge 20% more); 400,000 from the Black Market.', 'Superhuman Strength: restrained punch 5D6+15 S.D.C., punch 3D6 M.D., power punch 6D6 M.D. (counts as two attacks). Silver spikes add 1D6 S.D.C. against the undead', 1, NULL, 'Armor of Ithan: 60 M.D.C., 15 P.P.E. or 30 I.S.P., 10 minutes. Superhuman Strength: 10 P.P.E. or 20 I.S.P., 5 minutes', NULL, NULL, NULL, 100, 'Model TWA-1600 Exterminator E.B.A. The suit adds 1D4+5 to the wearer''s P.S. Fair mobility: -20% to climb, prowl, swim and acrobatics. No A.R. printed. M.D.C. by location: head 75, arms 40 each, legs 50 each, force field emitter 10 (called shot at -4), main body 100; the magic force field adds 60. Superhuman Strength: the feature text gives Supernatural P.S. 24 and the effects line gives P.S. 30 and P.E. 24, an inconsistency in the book; either way the wearer carries 1,500 lbs (675 kg). Room for up to two more features.', 'Rifts World Book 28: Arzno - Vampire Incursion p.87-88', NULL),
  ('ironwood-mage-armor', 'Ironwood Mage Armor', 'rifts', 'armor', 20, 75000, '75,000-85,000 credits for a basic suit; highly stylised suits cost two or three times as much.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'Model TWA-1000M. Wooden armor made Mega-Damage by the Earth Warlock spell Ironwood: not magical, with no Techno-Wizard features, made only by Techno-Wizards in Arzno (the Ironwood Armory is the best known maker), hard to repair and not environmental. It does not interfere with spell casting. Average mobility: -10% to climb, prowl, swim and acrobatics (a custom fit halves the prowl penalty). No A.R. printed. M.D.C. by location: head 30 (or a separate helmet), arms 20 each, legs 28 each, main body 60.', 'Rifts World Book 28: Arzno - Vampire Incursion p.88', NULL),
  ('ironwood-vampire-hunter-armor', 'Ironwood Vampire Hunter Armor', 'rifts', 'armor', 25, 85000, '85,000-95,000 credits for a basic suit; highly stylised suits cost two or three times as much.', 'Wooden strikes (elbow, knee, backhand, head butt) add 1D6 Hit Points to the undead and anything vulnerable to wood. Retractable forearm blade (Ironwood or silver) 2D6 Hit Points to vampires. Elbow spike 2D6 Hit Points to the undead. Spikes: 4D6 S.D.C. on a body block, 3D6 S.D.C. on a punch or kick, double as Hit Points to vampires and the wood-vulnerable', 0, NULL, NULL, NULL, NULL, NULL, 75, 'Model TWA-1000H, the Ironwood Hunter Armor: heavier than the mage armor, barbed and spiked, with some modern materials, and never fully environmental. Ironwood armor is wood made Mega-Damage by the Earth Warlock spell Ironwood: not magical, no Techno-Wizard features, made only by Techno-Wizards in Arzno (the Ironwood Armory is the best known maker). It does not interfere with spell casting. Average mobility: -10% to climb, -15% to prowl, swim and acrobatics. No A.R. printed. M.D.C. by location: head 40, arms 25 each, legs 35 each, main body 75.', 'Rifts World Book 28: Arzno - Vampire Incursion p.88-89', NULL),
  ('tw-ppe-battery', 'TW P.P.E. Battery', 'rifts', 'gear', NULL, NULL, 'No separate price; it comes built into each Imitator power armor.', NULL, 0, NULL, 'The series text gives a capacity of 60, 80 or 200 P.P.E.; each of the five Imitator suits prints 200', NULL, NULL, NULL, NULL, 'The P.P.E. battery of the Arzno Imitator power armor series: five diamonds of 2+ carats in a copper bar wrapped in gold and silver wire, hidden between the shoulder blades and destroyed with the main body. It powers only the suit''s Techno-Wizard features, never spell casting. Recharging: resting on a ley line restores 5 P.P.E. an hour (double at a nexus); fighting on a ley line gives 5 per melee round that does not accumulate; or a practitioner channels P.P.E. in, free from a friend, otherwise 30-50 credits a point (kind) or 100-600 (greedy).', 'Rifts World Book 28: Arzno - Vampire Incursion p.90', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 22 gear rows are in' AS assertion, count(*) AS got, 22 AS want
  FROM gear WHERE slug IN ('tw-stake-driver', 'tw-water-pistol', 'tw-water-rifle', 'tw-water-cannon-arzno', 'tw-wood-rail-gun', 'tw-vamp-killer-2000', 'tw-flash-bang-bomb', 'tw-lightning-mace', 'tw-active-shield', 'tw-climbing-claws', 'tw-bionic-climbing-claws', 'tw-concealment-cloak', 'tw-reading-glasses', 'tw-security-scanner', 'tw-tactical-team-targeting-system', 'tw-translator', 'light-tw-body-armor', 'tw-incursion-armor', 'tw-exterminator-armor', 'ironwood-mage-armor', 'ironwood-vampire-hunter-armor', 'tw-ppe-battery') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~244-arzno-gear.sql');
